// Mechanical Properties of Fluids (Physics) - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'
// Note: theory-focused, with only simple/light numerical questions included, per request.

export const MECHANICAL_PROPERTIES_FLUIDS = [

  // ============ PRESSURE: BASICS ============
  { id: 'mpf-1', type: 'mcq', question: 'The normal force exerted by a fluid per unit area on a surface it is in contact with is called:', options: ['Pressure', 'Density', 'Viscosity', 'Surface tension'], correctIndex: 0, explanation: 'Pressure is defined as the normal force exerted per unit area by a fluid on a surface.', difficulty: 'easy' },
  { id: 'mpf-2', type: 'mcq', question: 'Unlike force, pressure at a point within a fluid at rest is characterised as a:', options: ['Scalar quantity', 'Vector quantity', 'Dimensionless quantity', 'Fundamental (base) quantity'], correctIndex: 0, explanation: 'Although force is a vector, pressure at a point in a static fluid is a scalar quantity, since it acts equally in all directions at that point.', difficulty: 'medium' },
  { id: 'mpf-3', type: 'mcq', question: 'The SI unit of pressure is the:', options: ['Pascal (N/m²)', 'Newton', 'Joule', 'Watt'], correctIndex: 0, explanation: 'The SI unit of pressure is the pascal (Pa), equivalent to one newton per square metre.', difficulty: 'easy' },
  { id: 'mpf-4', type: 'mcq', question: 'The pressure exerted by the weight of the atmosphere on objects at the Earth\'s surface is called:', options: ['Atmospheric pressure', 'Gauge pressure, exclusively', 'Hydrostatic pressure, exclusively (unrelated to atmosphere)', 'Absolute pressure, incorrectly used as a synonym'], correctIndex: 0, explanation: 'Atmospheric pressure is the pressure exerted by the weight of the Earth\'s atmosphere at a given location, typically at or near sea level.', difficulty: 'easy' },
  { id: 'mpf-5', type: 'mcq', question: 'The pressure measured relative to atmospheric pressure (i.e., the difference between the actual/absolute pressure and atmospheric pressure) is called:', options: ['Gauge pressure', 'Absolute pressure, used interchangeably in every context', 'Atmospheric pressure, exclusively', 'Hydrostatic pressure, used interchangeably with gauge pressure'], correctIndex: 0, explanation: 'Gauge pressure is the pressure measured relative to atmospheric pressure, i.e., gauge pressure = absolute pressure - atmospheric pressure.', difficulty: 'medium' },
  { id: 'mpf-6', type: 'assertion', question: 'Assertion (A): Pressure at a point within a static fluid is the same in all directions.\nReason (R): If pressure varied with direction at a single point in a static fluid, an imbalance of forces would result, causing fluid motion, contradicting the assumption of static equilibrium.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The requirement of force balance for static equilibrium correctly explains why pressure at a point in a static fluid must be the same in all directions.', difficulty: 'hard' },
  { id: 'mpf-7', type: 'count', question: 'Consider the following statements about pressure:\n1. Pressure is a scalar quantity at a point within a fluid.\n2. The SI unit of pressure is the pascal.\n3. Gauge pressure is the same as absolute pressure, in every case.\n4. Atmospheric pressure results from the weight of the atmosphere.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — gauge pressure differs from absolute pressure by the amount of atmospheric pressure.', difficulty: 'medium' },

  // ============ VARIATION OF PRESSURE WITH DEPTH ============
  { id: 'mpf-8', type: 'mcq', question: 'As one moves deeper below the surface of a liquid (in a container open to the atmosphere), the pressure at that depth:', options: ['Increases with increasing depth', 'Decreases with increasing depth', 'Remains exactly constant, regardless of depth', 'Becomes zero at any depth greater than 1 metre'], correctIndex: 0, explanation: 'Pressure within a fluid increases with increasing depth, since deeper points must support the weight of the fluid column above them.', difficulty: 'easy' },
  { id: 'mpf-9', type: 'mcq', question: 'The pressure at a depth h below the free surface of a liquid of density ρ, due to the liquid column alone (excluding atmospheric pressure), is given by:', options: ['P = ρgh', 'P = ρg/h', 'P = ρ + gh', 'P = ρh/g'], correctIndex: 0, explanation: 'The hydrostatic pressure due to a liquid column of height h and density ρ is given by P = ρgh, where g is the acceleration due to gravity.', difficulty: 'medium' },
  { id: 'mpf-10', type: 'mcq', question: 'For a given liquid, the pressure at a certain depth depends on the depth and the density of the liquid, but is generally considered to be:', options: ['Independent of the shape or cross-sectional area of the container', 'Directly proportional to the cross-sectional area of the container', 'Inversely proportional to the cross-sectional area of the container', 'Undefined unless the container has a uniform, cylindrical shape'], correctIndex: 0, explanation: 'The hydrostatic pressure formula (P = ρgh) depends only on depth and density, and is independent of the shape or cross-sectional area of the container (this is sometimes referred to as the hydrostatic paradox).', difficulty: 'medium' },
  { id: 'mpf-11', type: 'assertion', question: 'Assertion (A): A deep-sea diver experiences significantly greater pressure than a swimmer near the surface of the same body of water.\nReason (R): Since hydrostatic pressure increases linearly with depth (P = ρgh), a diver at a greater depth experiences a correspondingly greater pressure due to the increased weight of the water column above them.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The direct proportionality between pressure and depth correctly explains why deep-sea divers experience significantly higher pressures than surface swimmers.', difficulty: 'medium' },
  { id: 'mpf-12', type: 'count', question: 'Consider the following statements about pressure variation with depth:\n1. Pressure in a liquid increases with increasing depth.\n2. Pressure at a given depth depends on the density of the liquid.\n3. Pressure at a given depth depends on the shape of the container.\n4. The formula P = ρgh gives the pressure due to a liquid column of height h.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — pressure at a given depth is independent of the shape of the container.', difficulty: 'medium' },

  // ============ PASCAL'S LAW ============
  { id: 'mpf-13', type: 'mcq', question: 'Pascal\'s Law states that pressure applied to an enclosed fluid at rest is transmitted:', options: ['Equally (undiminished) in all directions throughout the fluid', 'Only in the direction of the applied force, without any transmission in other directions', 'Only towards the bottom of the container, due to gravity', 'In a progressively diminishing manner, decreasing with distance from the point of application'], correctIndex: 0, explanation: 'Pascal\'s Law states that pressure applied at any point in an enclosed, incompressible fluid at rest is transmitted equally and undiminished throughout the fluid.', difficulty: 'easy' },
  { id: 'mpf-14', type: 'mcq', question: 'Pascal\'s Law forms the fundamental principle underlying the operation of:', options: ['Hydraulic machines, such as hydraulic lifts and hydraulic brakes', 'Only weather forecasting instruments', 'Only devices measuring temperature', 'Only devices used in electrical circuits'], correctIndex: 0, explanation: 'Pascal\'s Law is the operating principle behind hydraulic machines, including hydraulic lifts, brakes and presses.', difficulty: 'medium' },
  { id: 'mpf-15', type: 'mcq', question: 'In a hydraulic lift, a small force applied to a piston of small cross-sectional area can be used to lift a much heavier load, applied through a piston with a larger cross-sectional area, because:', options: ['According to Pascal\'s Law, the pressure is transmitted equally, and force equals pressure multiplied by area, so a larger area results in a proportionally larger force', 'The fluid inside the system somehow generates additional energy from nowhere', 'The smaller piston is always made of a much stronger material', 'This effect only works with gases, never with liquids'], correctIndex: 0, explanation: 'Since pressure is transmitted equally throughout the enclosed fluid (Pascal\'s Law), and force = pressure × area, a small force on a small-area piston can produce a much larger force on a larger-area piston.', difficulty: 'medium' },
  { id: 'mpf-16', type: 'assertion', question: 'Assertion (A): A hydraulic lift allows a person to lift a very heavy vehicle using a relatively small applied force.\nReason (R): By Pascal\'s Law, the pressure applied at the small piston is transmitted equally throughout the enclosed fluid, and since the output piston has a much larger cross-sectional area, the resulting output force is correspondingly amplified.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The mechanism of pressure transmission and force amplification via differing piston areas, as described by Pascal\'s Law, correctly explains the operating principle of a hydraulic lift.', difficulty: 'medium' },
  { id: 'mpf-17', type: 'count', question: 'Consider the following statements about Pascal\'s Law:\n1. Pressure applied to an enclosed fluid is transmitted equally in all directions.\n2. Pascal\'s Law is the basis of hydraulic lifts and brakes.\n3. In a hydraulic lift, the output force is smaller than the input force, in every case.\n4. A larger piston area results in a proportionally larger output force, for a given transmitted pressure.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the output force in a hydraulic lift is generally larger (not smaller) than the input force, due to the larger output piston area.', difficulty: 'medium' },

  // ============ STREAMLINE FLOW AND EQUATION OF CONTINUITY ============
  { id: 'mpf-18', type: 'mcq', question: 'A type of fluid flow in which every particle passing through a given point follows the same path as the particle before it, with the path lines not crossing each other, is called:', options: ['Streamline (laminar) flow', 'Turbulent flow', 'Random flow, exclusively', 'Chaotic flow, used interchangeably with laminar flow'], correctIndex: 0, explanation: 'Streamline (laminar) flow is characterised by smooth, orderly fluid motion, with particles following well-defined, non-intersecting paths.', difficulty: 'easy' },
  { id: 'mpf-19', type: 'mcq', question: 'A type of fluid flow characterised by irregular, chaotic motion, with eddies and vortices forming, typically occurring at high flow velocities, is called:', options: ['Turbulent flow', 'Streamline (laminar) flow', 'Steady flow, used interchangeably with turbulent flow', 'Uniform flow, used interchangeably with turbulent flow'], correctIndex: 0, explanation: 'Turbulent flow is characterised by irregular, chaotic fluid motion with eddies and vortices, typically occurring beyond a certain critical velocity.', difficulty: 'easy' },
  { id: 'mpf-20', type: 'mcq', question: 'The velocity below which fluid flow remains streamline (laminar), and above which it tends to become turbulent, is called the:', options: ['Critical velocity', 'Terminal velocity, exclusively', 'Escape velocity, exclusively (unrelated to fluid flow)', 'Orbital velocity, exclusively (unrelated to fluid flow)'], correctIndex: 0, explanation: 'Critical velocity is the specific flow velocity below which the flow remains laminar and above which it becomes turbulent.', difficulty: 'medium' },
  { id: 'mpf-21', type: 'mcq', question: 'The dimensionless number used to predict whether a given fluid flow will be laminar or turbulent, based on factors including flow velocity, fluid density, viscosity, and the characteristic dimension of the flow, is called the:', options: ['Reynolds number', 'Mach number, exclusively used for compressible/high-speed flow, unrelated here', 'Poisson\'s ratio, exclusively used for solids', 'Prandtl number, unrelated to this specific prediction'], correctIndex: 0, explanation: 'The Reynolds number is a dimensionless quantity used to predict the transition between laminar and turbulent flow regimes.', difficulty: 'medium' },
  { id: 'mpf-22', type: 'mcq', question: 'A relatively low value of the Reynolds number generally indicates that the flow is likely to be:', options: ['Laminar (streamline)', 'Turbulent', 'Neither laminar nor turbulent, but a third, undefined category', 'Impossible to determine without additional data, regardless of the Reynolds number value'], correctIndex: 0, explanation: 'A low Reynolds number generally indicates that viscous forces dominate over inertial forces, favouring laminar (streamline) flow.', difficulty: 'medium' },
  { id: 'mpf-23', type: 'mcq', question: 'The Equation of Continuity, applicable to steady, incompressible fluid flow, states that the product of cross-sectional area (A) and flow velocity (v) at any point along a flow tube:', options: ['Remains constant along the entire flow tube (A1v1 = A2v2)', 'Continuously increases along the flow tube', 'Continuously decreases along the flow tube', 'Has no defined relationship between different points along the flow tube'], correctIndex: 0, explanation: 'The equation of continuity, A1v1 = A2v2, expresses conservation of mass for an incompressible fluid in steady flow.', difficulty: 'medium' },
  { id: 'mpf-24', type: 'mcq', question: 'According to the Equation of Continuity, in a pipe that narrows (decreases in cross-sectional area) along its length, the velocity of an incompressible fluid flowing through it must:', options: ['Increase, to maintain a constant volume flow rate', 'Decrease, to maintain a constant volume flow rate', 'Remain exactly unchanged, regardless of the change in cross-sectional area', 'Become zero, at any point where the pipe narrows'], correctIndex: 0, explanation: 'Since A1v1 = A2v2 must hold, a decrease in cross-sectional area must be compensated by a proportional increase in flow velocity, to keep the volume flow rate constant.', difficulty: 'medium' },
  { id: 'mpf-25', type: 'assertion', question: 'Assertion (A): Water flows faster through a narrow section of a garden hose (when the nozzle is partially covered) compared to the wider section.\nReason (R): According to the Equation of Continuity, for an incompressible fluid in steady flow, a decrease in cross-sectional area must be compensated by a corresponding increase in flow velocity, to maintain a constant volume flow rate.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The requirement of constant volume flow rate, as expressed by the equation of continuity, correctly explains why water flows faster through a narrowed section of a hose.', difficulty: 'medium' },
  { id: 'mpf-26', type: 'count', question: 'Consider the following statements about fluid flow:\n1. Laminar flow is characterised by smooth, non-intersecting path lines.\n2. Turbulent flow typically occurs at velocities below the critical velocity.\n3. Reynolds number helps predict whether flow will be laminar or turbulent.\n4. The equation of continuity states that A × v remains constant for steady, incompressible flow.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — turbulent flow typically occurs above (not below) the critical velocity.', difficulty: 'medium' },
  { id: 'mpf-27', type: 'matching', question: 'Match Column I (fluid flow term) with Column II (description):\nColumn I: A. Laminar flow  B. Turbulent flow  C. Critical velocity  D. Reynolds number\nColumn II: i. Predicts laminar vs turbulent flow  ii. Chaotic, irregular flow with eddies  iii. Smooth, orderly, non-intersecting paths  iv. Threshold speed for transition to turbulence', options: ['A-iii, B-ii, C-iv, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-iv, C-ii, D-i', 'A-ii, B-iii, C-i, D-iv'], correctIndex: 0, explanation: 'Laminar flow — smooth, orderly paths; Turbulent flow — chaotic with eddies; Critical velocity — transition threshold; Reynolds number — predicts flow regime.', difficulty: 'medium' },

  // ============ BERNOULLI'S PRINCIPLE ============
  { id: 'mpf-28', type: 'mcq', question: 'Bernoulli\'s Principle, applicable to steady, incompressible, non-viscous fluid flow, is fundamentally a statement of the:', options: ['Conservation of energy, as applied to flowing fluids', 'Conservation of mass, exclusively (this is more accurately the equation of continuity)', 'Conservation of angular momentum, applied to fluid motion', 'Newton\'s Third Law, applied to fluid particles'], correctIndex: 0, explanation: 'Bernoulli\'s Principle is essentially an expression of the conservation of energy (accounting for pressure energy, kinetic energy, and potential energy) applied to a flowing, ideal fluid.', difficulty: 'medium' },
  { id: 'mpf-29', type: 'mcq', question: 'Bernoulli\'s equation states that, for an ideal (non-viscous, incompressible) fluid in steady flow, the sum of pressure energy, kinetic energy, and gravitational potential energy per unit volume:', options: ['Remains constant along a streamline', 'Continuously increases along a streamline', 'Continuously decreases along a streamline', 'Has no defined relationship along a streamline'], correctIndex: 0, explanation: 'Bernoulli\'s equation states that the sum P + (1/2)ρv² + ρgh remains constant along a streamline for an ideal fluid in steady flow.', difficulty: 'medium' },
  { id: 'mpf-30', type: 'mcq', question: 'According to Bernoulli\'s Principle, in a horizontal pipe of varying cross-sectional area (where gravitational potential energy terms remain constant), regions where the fluid flows faster generally have:', options: ['Lower pressure', 'Higher pressure', 'Exactly the same pressure as slower-flowing regions', 'Pressure that is completely unrelated to flow speed'], correctIndex: 0, explanation: 'Bernoulli\'s Principle implies an inverse relationship between flow speed and pressure (at the same height) — faster-flowing regions have lower pressure.', difficulty: 'medium' },
  { id: 'mpf-31', type: 'mcq', question: 'Bernoulli\'s Principle helps explain the phenomenon of "dynamic lift" experienced by an airplane wing, primarily because:', options: ['Air flows faster over the curved upper surface of the wing than beneath it, resulting in lower pressure above and a net upward force', 'Air flows slower over the upper surface than beneath it, resulting in higher pressure above and a net downward force', 'The wing has no interaction with airflow at all; lift is generated purely by the engines', 'Bernoulli\'s Principle is entirely unrelated to aerodynamic lift'], correctIndex: 0, explanation: 'The differential airspeed over an airplane wing\'s curved upper surface versus its lower surface, according to Bernoulli\'s Principle, creates a pressure difference that contributes to lift.', difficulty: 'medium' },
  { id: 'mpf-32', type: 'mcq', question: 'A venturi meter, a device used to measure the flow rate of a fluid through a pipe, operates based on the principle that:', options: ['A constriction in the pipe causes an increase in flow speed and a corresponding decrease in pressure, which can be measured to determine flow rate', 'A constriction in the pipe has no measurable effect on either speed or pressure', 'Flow speed decreases and pressure increases at a constriction, with no useful relationship for measurement', 'Venturi meters function based on principles entirely unrelated to Bernoulli\'s Principle'], correctIndex: 0, explanation: 'A venturi meter uses the pressure drop associated with increased flow speed at a constriction (per Bernoulli\'s Principle) to determine the flow rate of the fluid.', difficulty: 'medium' },
  { id: 'mpf-33', type: 'mcq', question: 'An atomizer (spray device), such as those used in perfume bottles, relies on Bernoulli\'s Principle to function, using the principle that:', options: ['A rapid stream of air blown across the top of a narrow tube creates a region of low pressure, drawing liquid up the tube to be atomised into a fine spray', 'A rapid stream of air blown across the tube creates high pressure, pushing liquid downward and preventing any spray formation', 'Atomizers function purely through gravitational effects, with no relation to air pressure', 'Atomizers require heating of the liquid, unrelated to any pressure-based mechanism'], correctIndex: 0, explanation: 'In an atomizer, air blown rapidly across a tube opening creates a low-pressure region (Bernoulli effect), drawing liquid upward to be atomised into a spray.', difficulty: 'medium' },
  { id: 'mpf-34', type: 'assertion', question: 'Assertion (A): Two ships moving parallel to each other, close together, in the same direction, tend to experience an attractive force pulling them towards each other.\nReason (R): The water flowing in the narrow channel between the two ships moves faster than the water on the outer sides, resulting in lower pressure between the ships (as per Bernoulli\'s Principle), creating a net force that pulls them together.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The pressure difference resulting from differential flow speeds between and around the ships, consistent with Bernoulli\'s Principle, correctly explains the observed attractive tendency.', difficulty: 'hard' },
  { id: 'mpf-35', type: 'count', question: 'Consider the following statements about Bernoulli\'s Principle:\n1. It is essentially an application of energy conservation to fluid flow.\n2. Faster flow speed is generally associated with lower pressure, at the same height.\n3. Bernoulli\'s Principle explains the operation of venturi meters and atomizers.\n4. Bernoulli\'s Principle applies equally well to viscous, turbulent flows, without any restriction.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — Bernoulli\'s Principle, in its standard form, applies specifically to ideal (non-viscous), steady, incompressible flow, not general viscous/turbulent flow.', difficulty: 'medium' },
  { id: 'mpf-36', type: 'statement', question: 'Statement I: Bernoulli\'s Principle applies specifically to ideal fluids, assuming no viscosity and steady, incompressible flow.\nStatement II: Real fluids, which have some viscosity, may show deviations from the idealised predictions of Bernoulli\'s equation.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly identify the idealised assumptions underlying Bernoulli\'s Principle and the resulting deviations observed in real, viscous fluids.', difficulty: 'medium' },
  { id: 'mpf-37', type: 'matching', question: 'Match Column I (application) with Column II (underlying Bernoulli-based mechanism):\nColumn I: A. Airplane wing lift  B. Venturi meter  C. Atomizer\nColumn II: i. Constriction causes speed increase and pressure drop, measured for flow rate  ii. Differential airspeed over curved surfaces creates pressure difference  iii. Air stream creates low pressure, drawing liquid upward', options: ['A-ii, B-i, C-iii', 'A-i, B-ii, C-iii', 'A-iii, B-i, C-ii', 'A-ii, B-iii, C-i'], correctIndex: 0, explanation: 'Airplane wing lift — differential airspeed creating pressure difference; Venturi meter — constriction-based flow measurement; Atomizer — low-pressure air stream drawing liquid upward.', difficulty: 'medium' },

  // ============ TORRICELLI'S LAW (SPEED OF EFFLUX) ============
  { id: 'mpf-38', type: 'mcq', question: 'Torricelli\'s Law, derived using Bernoulli\'s Principle, describes the speed at which a liquid flows out (efflux) from a small opening in a container, related to:', options: ['The height (depth) of the liquid column above the opening', 'The colour of the liquid, exclusively', 'The temperature of the liquid, exclusively, with no relation to height', 'The material of the container, exclusively'], correctIndex: 0, explanation: 'Torricelli\'s Law relates the efflux (outflow) speed of a liquid from a small opening to the height of the liquid column above that opening.', difficulty: 'medium' },
  { id: 'mpf-39', type: 'mcq', question: 'According to Torricelli\'s Law, the speed of efflux (v) of a liquid from a small opening, located at a depth h below the free surface of the liquid in an open container, is given by:', options: ['v = √(2gh)', 'v = 2gh', 'v = √(gh)', 'v = gh²'], correctIndex: 0, explanation: 'Torricelli\'s Law gives the efflux speed as v = √(2gh), analogous to the speed acquired by an object falling freely through the same height h.', difficulty: 'medium' },
  { id: 'mpf-40', type: 'assertion', question: 'Assertion (A): The speed of efflux of a liquid from a hole near the bottom of a tank is the same as the speed an object would acquire if it fell freely from the height of the liquid surface above the hole.\nReason (R): Torricelli\'s Law, derived from Bernoulli\'s Principle applied to this situation, gives an efflux speed formula (v = √(2gh)) that is mathematically identical to the free-fall speed formula for an object falling through the same height h.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The mathematical equivalence between the Torricelli efflux formula and the free-fall speed formula correctly explains why the two speeds coincide, as stated in the assertion.', difficulty: 'hard' },

  // ============ VISCOSITY ============
  { id: 'mpf-41', type: 'mcq', question: 'The property of a fluid by virtue of which it offers resistance to the relative motion between its adjacent layers is called:', options: ['Viscosity', 'Surface tension', 'Density, exclusively unrelated to internal friction', 'Buoyancy, exclusively unrelated to internal friction'], correctIndex: 0, explanation: 'Viscosity refers to a fluid\'s internal resistance to flow, arising from friction between adjacent fluid layers moving at different velocities.', difficulty: 'easy' },
  { id: 'mpf-42', type: 'mcq', question: 'Viscosity can be thought of as a kind of internal friction within a fluid, arising due to:', options: ['The relative motion between adjacent layers of the fluid, moving at different velocities', 'The total mass of the fluid, exclusively, with no relation to relative layer motion', 'The colour or transparency of the fluid, exclusively', 'The container holding the fluid, exclusively'], correctIndex: 0, explanation: 'Viscosity arises from the relative motion of adjacent fluid layers, which exert a frictional (tangential) force on each other.', difficulty: 'medium' },
  { id: 'mpf-43', type: 'mcq', question: 'For most liquids (such as water and oils), viscosity generally decreases with:', options: ['Increasing temperature', 'Decreasing temperature', 'No relationship whatsoever with temperature', 'Increasing pressure exclusively, with no relation to temperature'], correctIndex: 0, explanation: 'For most liquids, viscosity generally decreases as temperature increases, since increased thermal energy reduces intermolecular attractive forces.', difficulty: 'medium' },
  { id: 'mpf-44', type: 'mcq', question: 'For most gases, viscosity generally shows the opposite trend compared to liquids, meaning it generally:', options: ['Increases with increasing temperature', 'Decreases with increasing temperature, exactly as in liquids', 'Remains exactly constant with temperature, unlike liquids', 'Becomes zero at any temperature above 0°C'], correctIndex: 0, explanation: 'Unlike liquids, gas viscosity generally increases with increasing temperature, due to increased molecular collision rates at higher temperatures.', difficulty: 'medium' },
  { id: 'mpf-45', type: 'mcq', question: 'Highly viscous fluids, such as honey or thick syrup, are characterised by:', options: ['A greater resistance to flow, and hence a slower rate of flow under a given applied force, compared to less viscous fluids like water', 'A lower resistance to flow, flowing more easily and quickly than water under a similar applied force', 'No resistance to flow at all, flowing instantaneously', 'Exactly the same flow behaviour as water, in every circumstance'], correctIndex: 0, explanation: 'Highly viscous fluids offer greater resistance to flow, resulting in slower movement under a given applied force compared to less viscous fluids.', difficulty: 'medium' },
  { id: 'mpf-46', type: 'assertion', question: 'Assertion (A): Honey flows much more slowly than water when poured from a container.\nReason (R): Honey has a significantly higher viscosity than water, meaning it offers greater internal resistance to flow, resulting in a slower observed flow rate under similar conditions.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The significantly higher viscosity of honey compared to water correctly explains its observed slower flow rate.', difficulty: 'medium' },
  { id: 'mpf-47', type: 'count', question: 'Consider the following statements about viscosity:\n1. Viscosity refers to a fluid\'s internal resistance to flow.\n2. Viscosity of most liquids generally decreases with increasing temperature.\n3. Viscosity of most gases generally decreases with increasing temperature, similar to liquids.\n4. Highly viscous fluids flow more slowly than less viscous fluids, under similar conditions.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — gas viscosity generally increases (not decreases) with increasing temperature, unlike liquids.', difficulty: 'medium' },

  // ============ STOKES' LAW AND TERMINAL VELOCITY ============
  { id: 'mpf-48', type: 'mcq', question: 'Stokes\' Law gives the viscous drag force experienced by a small spherical object moving through a viscous fluid, at low speeds, relating this force to the object\'s radius, the fluid\'s viscosity, and the object\'s:', options: ['Velocity relative to the fluid', 'Colour, exclusively unrelated to drag force', 'Chemical composition, exclusively unrelated to drag force', 'Electric charge, exclusively unrelated to viscous drag'], correctIndex: 0, explanation: 'Stokes\' Law relates the viscous drag force on a small sphere to its radius, the fluid\'s viscosity coefficient, and the object\'s velocity relative to the fluid.', difficulty: 'medium' },
  { id: 'mpf-49', type: 'mcq', question: 'When a small spherical object falls through a viscous fluid under gravity, it eventually reaches a constant maximum speed, at which the net force on it becomes zero; this speed is called the:', options: ['Terminal velocity', 'Escape velocity, exclusively unrelated to fluid resistance', 'Critical velocity, used interchangeably with terminal velocity in every context', 'Orbital velocity, exclusively unrelated to falling through fluids'], correctIndex: 0, explanation: 'Terminal velocity is the constant maximum speed reached by an object falling through a viscous fluid, at which the net force (gravity, buoyancy, and viscous drag) becomes zero.', difficulty: 'medium' },
  { id: 'mpf-50', type: 'mcq', question: 'As a spherical object falls through a viscous fluid and its speed increases, the viscous drag force acting on it (opposing its motion) also generally:', options: ['Increases, eventually balancing the net downward force and resulting in terminal velocity', 'Decreases, allowing the object to continue accelerating indefinitely', 'Remains exactly constant, regardless of the object\'s speed', 'Becomes negative, effectively pulling the object downward even faster'], correctIndex: 0, explanation: 'As speed increases, the viscous drag force (proportional to velocity, per Stokes\' Law) also increases, eventually balancing the net downward force and resulting in a constant terminal velocity.', difficulty: 'medium' },
  { id: 'mpf-51', type: 'mcq', question: 'At terminal velocity, the net force on a falling spherical object in a viscous fluid is zero, meaning that the weight of the object is balanced by the sum of:', options: ['The buoyant force and the viscous drag force', 'Only the buoyant force, with viscous drag being negligible at terminal velocity', 'Only the viscous drag force, with buoyancy being negligible at terminal velocity', 'Neither buoyant force nor viscous drag, since terminal velocity implies zero force of any kind'], correctIndex: 0, explanation: 'At terminal velocity, the object\'s weight is balanced by the combined upward forces of buoyancy and viscous drag, resulting in zero net force and hence constant velocity.', difficulty: 'medium' },
  { id: 'mpf-52', type: 'assertion', question: 'Assertion (A): A small pebble dropped into a container of thick oil quickly reaches a constant (terminal) velocity, rather than continuing to accelerate indefinitely.\nReason (R): As the pebble\'s speed increases, the viscous drag force (which increases with speed) eventually balances the net downward force due to gravity (minus buoyancy), resulting in zero net force and a constant terminal velocity.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The velocity-dependent nature of viscous drag, eventually balancing the net gravitational force, correctly explains why the pebble reaches a constant terminal velocity rather than accelerating indefinitely.', difficulty: 'medium' },
  { id: 'mpf-53', type: 'count', question: 'Consider the following statements about Stokes\' Law and terminal velocity:\n1. Stokes\' Law applies to small spherical objects moving through a viscous fluid at low speeds.\n2. Viscous drag force generally increases with the object\'s speed.\n3. At terminal velocity, the net force on the falling object is zero.\n4. Terminal velocity is reached only when buoyant force is exactly zero.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — buoyant force does contribute (need not be zero) to the force balance at terminal velocity; it acts alongside viscous drag against gravity.', difficulty: 'medium' },

  // ============ SURFACE TENSION ============
  { id: 'mpf-54', type: 'mcq', question: 'The property of a liquid surface that causes it to behave like a stretched elastic membrane, tending to minimise its surface area, is called:', options: ['Surface tension', 'Viscosity', 'Capillarity, exclusively unrelated to surface behaviour', 'Buoyancy, exclusively unrelated to surface behaviour'], correctIndex: 0, explanation: 'Surface tension is the property of a liquid surface that causes it to behave like a stretched membrane, minimising its surface area.', difficulty: 'easy' },
  { id: 'mpf-55', type: 'mcq', question: 'Surface tension arises fundamentally due to:', options: ['The unequal (net inward) cohesive forces experienced by molecules at the surface of a liquid, compared to molecules within the bulk of the liquid', 'Gravitational attraction between the liquid and the container walls, exclusively', 'The temperature of the liquid, exclusively unrelated to intermolecular forces', 'Electrical charges present in the liquid, exclusively'], correctIndex: 0, explanation: 'Surface tension arises because molecules at the liquid surface experience a net inward cohesive force (since they lack neighbouring molecules above them), unlike molecules within the bulk of the liquid.', difficulty: 'medium' },
  { id: 'mpf-56', type: 'mcq', question: 'Surface tension is defined quantitatively as the force acting per unit length along a line drawn on the liquid surface, and is measured in units of:', options: ['Newton per metre (N/m)', 'Newton per square metre (N/m²)', 'Newton-metre (N·m)', 'Newton only, without any length dependence'], correctIndex: 0, explanation: 'Surface tension is defined as force per unit length, with SI units of newton per metre (N/m).', difficulty: 'medium' },
  { id: 'mpf-57', type: 'mcq', question: 'The observation that small water droplets tend to assume a nearly spherical shape (in the absence of significant external forces like gravity) is best explained by:', options: ['Surface tension, which tends to minimise surface area, and a sphere has the minimum surface area for a given volume', 'Viscosity, which has no relation to droplet shape', 'Buoyancy, which is unrelated to the shape of small droplets', 'Atmospheric pressure alone, without any contribution from surface tension'], correctIndex: 0, explanation: 'Since a sphere has the minimum surface area for a given volume, surface tension\'s tendency to minimise surface area explains why small droplets assume a nearly spherical shape.', difficulty: 'medium' },
  { id: 'mpf-58', type: 'mcq', question: 'The energy associated with the extra surface area of a liquid, arising due to surface tension, is called:', options: ['Surface energy', 'Kinetic energy of the liquid, exclusively', 'Gravitational potential energy of the liquid, exclusively', 'Thermal energy of the liquid, exclusively'], correctIndex: 0, explanation: 'Surface energy refers to the extra potential energy possessed by molecules at the surface of a liquid, associated with surface tension.', difficulty: 'medium' },
  { id: 'mpf-59', type: 'mcq', question: 'Certain small insects, such as water striders, are able to walk on the surface of water primarily due to:', options: ['Surface tension, which provides sufficient upward force to support the insect\'s weight without breaking the surface', 'Viscosity of the water, exclusively unrelated to surface support', 'The insect\'s significant buoyant density, unrelated to surface effects', 'A biological ability to defy gravity entirely, unrelated to any physical property of water'], correctIndex: 0, explanation: 'Surface tension provides an upward supporting force, sufficient to counteract the small weight of insects like water striders, allowing them to walk on the water surface without breaking it.', difficulty: 'medium' },
  { id: 'mpf-60', type: 'assertion', question: 'Assertion (A): It generally requires additional energy input to increase the surface area of a liquid.\nReason (R): Since surface tension causes surface molecules to experience a net inward force, increasing surface area requires work to be done against this force, thereby increasing the surface (potential) energy of the system.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The work required against the net inward cohesive forces at the surface correctly explains why increasing surface area requires additional energy input.', difficulty: 'hard' },
  { id: 'mpf-61', type: 'count', question: 'Consider the following statements about surface tension:\n1. Surface tension arises due to unequal cohesive forces experienced by surface molecules.\n2. Surface tension is measured in newton per metre.\n3. Water droplets tend to become spherical because a sphere minimises surface area for a given volume.\n4. Increasing the surface area of a liquid requires no additional energy input.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — increasing surface area does require additional energy input, due to surface tension.', difficulty: 'medium' },

  // ============ ANGLE OF CONTACT AND CAPILLARITY ============
  { id: 'mpf-62', type: 'mcq', question: 'The angle measured between the tangent to the liquid surface at the point of contact with a solid surface and the solid surface itself (measured within the liquid) is called the:', options: ['Angle of contact', 'Angle of incidence, exclusively unrelated to liquid-solid interactions', 'Critical angle, exclusively unrelated to this context', 'Angle of refraction, exclusively unrelated to this context'], correctIndex: 0, explanation: 'The angle of contact is defined between the liquid surface tangent (at the point of contact with a solid) and the solid surface itself.', difficulty: 'medium' },
  { id: 'mpf-63', type: 'mcq', question: 'A liquid is said to "wet" a solid surface when the angle of contact is:', options: ['Less than 90 degrees (an acute angle)', 'Greater than 90 degrees (an obtuse angle)', 'Exactly 180 degrees, in every wetting scenario', 'Undefined, since wetting has no relationship to the angle of contact'], correctIndex: 0, explanation: 'A liquid is said to wet a surface when the angle of contact is less than 90°, indicating that adhesive forces (between liquid and solid) dominate over cohesive forces (within the liquid).', difficulty: 'medium' },
  { id: 'mpf-64', type: 'mcq', question: 'When the angle of contact between a liquid and a solid surface is greater than 90 degrees, the liquid is generally said to:', options: ['Not wet the surface', 'Wet the surface completely', 'Have zero surface tension', 'Have infinite surface tension'], correctIndex: 0, explanation: 'When the angle of contact exceeds 90°, cohesive forces within the liquid dominate over adhesive forces with the solid, and the liquid does not wet the surface.', difficulty: 'medium' },
  { id: 'mpf-65', type: 'mcq', question: 'The rise (or, in some cases, depression) of a liquid within a narrow tube, when the tube is placed in a container of that liquid, is called:', options: ['Capillary action (capillarity)', 'Viscous flow, exclusively unrelated to narrow tubes', 'Turbulence, exclusively unrelated to this phenomenon', 'Buoyancy, exclusively unrelated to narrow-tube behaviour'], correctIndex: 0, explanation: 'Capillary action (capillarity) refers to the rise or depression of a liquid within a narrow tube, arising from surface tension and adhesive/cohesive forces.', difficulty: 'medium' },
  { id: 'mpf-66', type: 'mcq', question: 'For liquids that wet the tube material (angle of contact less than 90°), such as water in a clean glass tube, capillary action generally causes the liquid to:', options: ['Rise within the narrow tube, above the level of the surrounding liquid', 'Be depressed within the narrow tube, below the level of the surrounding liquid', 'Show no change in level, regardless of the tube\'s narrowness', 'Immediately overflow out of the tube, regardless of tube diameter'], correctIndex: 0, explanation: 'For liquids that wet the tube (angle of contact < 90°), such as water in glass, capillary action causes the liquid to rise within the narrow tube.', difficulty: 'medium' },
  { id: 'mpf-67', type: 'mcq', question: 'For liquids that do NOT wet the tube material (angle of contact greater than 90°), such as mercury in a glass tube, capillary action generally causes the liquid to:', options: ['Be depressed within the narrow tube, below the level of the surrounding liquid', 'Rise within the narrow tube, above the level of the surrounding liquid', 'Show no change in level, regardless of the tube\'s narrowness', 'Behave identically to water in glass, with no observable difference'], correctIndex: 0, explanation: 'For non-wetting liquids like mercury in glass (angle of contact > 90°), capillary action causes depression rather than rise within the narrow tube.', difficulty: 'medium' },
  { id: 'mpf-68', type: 'mcq', question: 'The height to which a liquid rises (or is depressed) within a capillary tube is generally inversely related to the:', options: ['Radius of the capillary tube (narrower tubes generally show greater rise/depression)', 'Surface tension of the liquid (with higher surface tension causing less rise, contrary to observed behaviour)', 'Density of the liquid, with denser liquids always rising more, contrary to observed behaviour', 'None of these factors have any bearing on capillary rise/depression'], correctIndex: 0, explanation: 'Capillary rise (or depression) height is inversely proportional to the radius of the capillary tube — narrower tubes generally produce a greater rise or depression.', difficulty: 'medium' },
  { id: 'mpf-69', type: 'assertion', question: 'Assertion (A): Water rises in a narrow glass capillary tube, while mercury is depressed in a similar tube.\nReason (R): Water has an angle of contact with glass that is less than 90° (indicating wetting behaviour), while mercury has an angle of contact with glass greater than 90° (indicating non-wetting behaviour), leading to opposite capillary effects.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The contrasting wetting behaviours of water and mercury with glass, reflected in their differing angles of contact, correctly explain the opposite capillary effects (rise versus depression) observed.', difficulty: 'medium' },
  { id: 'mpf-70', type: 'assertion', question: 'Assertion (A): Capillary action plays an important role in the movement of water through narrow spaces in plant stems and soil.\nReason (R): Surface tension-driven capillary action, occurring within the narrow, tube-like structures found in these natural systems, contributes to the transport of water against gravity.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The relevance of surface tension-driven capillary action within narrow natural channels correctly explains its role in phenomena like water movement in plants and soil.', difficulty: 'medium' },
  { id: 'mpf-71', type: 'count', question: 'Consider the following statements about angle of contact and capillarity:\n1. A liquid wets a surface when the angle of contact is less than 90 degrees.\n2. Water rises in a narrow glass capillary tube.\n3. Mercury rises in a narrow glass capillary tube, similar to water.\n4. Capillary rise is generally greater in narrower tubes.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — mercury is depressed (not risen) in a narrow glass capillary tube, due to its non-wetting behaviour with glass.', difficulty: 'medium' },
  { id: 'mpf-72', type: 'matching', question: 'Match Column I (liquid-surface pair) with Column II (angle of contact/behaviour):\nColumn I: A. Water on clean glass  B. Mercury on glass\nColumn II: i. Angle of contact > 90°, does not wet, depression in capillary  ii. Angle of contact < 90°, wets, rises in capillary', options: ['A-ii, B-i', 'A-i, B-ii', 'Both A and B show identical angle of contact', 'Both A and B show identical capillary behaviour'], correctIndex: 0, explanation: 'Water on clean glass — wets, angle < 90°, capillary rise; Mercury on glass — does not wet, angle > 90°, capillary depression.', difficulty: 'medium' },

  // ============ EXCESS PRESSURE INSIDE A DROP AND BUBBLE ============
  { id: 'mpf-73', type: 'mcq', question: 'Due to surface tension, the pressure inside a spherical liquid drop is generally:', options: ['Greater than the pressure outside the drop', 'Less than the pressure outside the drop', 'Exactly equal to the pressure outside the drop, regardless of surface tension', 'Undefined, since pressure has no meaning inside a liquid drop'], correctIndex: 0, explanation: 'Due to surface tension, the pressure inside a spherical liquid drop is greater than the pressure outside it, as surface tension causes the curved surface to compress the interior.', difficulty: 'medium' },
  { id: 'mpf-74', type: 'mcq', question: 'For a spherical soap bubble (which has two liquid surfaces — an inner and an outer surface, both contributing to surface tension), the excess pressure inside the bubble compared to a simple liquid drop of the same radius is generally:', options: ['Twice as much, since a bubble has two surfaces contributing to the effect, compared to one surface for a simple drop', 'Exactly the same, since the number of surfaces has no bearing on excess pressure', 'Half as much, since a bubble has thinner walls compared to a solid drop', 'Zero, since bubbles have no measurable surface tension effect'], correctIndex: 0, explanation: 'Since a soap bubble has two surfaces (inner and outer) both contributing to surface tension effects, the excess pressure inside a bubble is twice that of a simple liquid drop of the same radius (for the same surface tension).', difficulty: 'hard' },
  { id: 'mpf-75', type: 'mcq', question: 'For a given liquid (with fixed surface tension), the excess pressure inside a spherical drop is generally related to the drop\'s radius (r) such that:', options: ['Smaller drops (smaller r) have greater excess pressure than larger drops', 'Larger drops (larger r) have greater excess pressure than smaller drops', 'Excess pressure is completely independent of the drop\'s radius', 'Excess pressure becomes negative for very small drops'], correctIndex: 0, explanation: 'Since excess pressure is inversely proportional to radius, smaller drops experience greater excess pressure than larger drops, for the same liquid and surface tension.', difficulty: 'medium' },
  { id: 'mpf-76', type: 'assertion', question: 'Assertion (A): It requires greater pressure to blow a smaller soap bubble than a larger one.\nReason (R): Since the excess pressure inside a spherical bubble is inversely proportional to its radius, a smaller bubble requires a correspondingly greater excess pressure to be maintained (or formed), compared to a larger bubble.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The inverse relationship between excess pressure and bubble radius correctly explains why smaller bubbles require greater pressure to blow and maintain, compared to larger ones.', difficulty: 'hard' },
  { id: 'mpf-77', type: 'count', question: 'Consider the following statements about excess pressure due to surface tension:\n1. Pressure inside a liquid drop is generally greater than outside.\n2. A soap bubble has two surfaces contributing to surface tension effects.\n3. Excess pressure inside a bubble is directly proportional to its radius (larger bubbles have greater excess pressure).\n4. Smaller drops experience greater excess pressure than larger drops.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — excess pressure is inversely (not directly) proportional to radius; smaller radii give greater excess pressure.', difficulty: 'hard' },

  // ============ MIXED / REVISION ============
  { id: 'mpf-78', type: 'mcq', question: 'Which of the following pairs is INCORRECTLY matched?', options: ['Pascal\'s Law — Pressure transmitted equally in enclosed fluid', 'Bernoulli\'s Principle — Conservation of energy in fluid flow', 'Stokes\' Law — Viscous drag on a small sphere', 'Torricelli\'s Law — Excess pressure inside a soap bubble'], correctIndex: 3, explanation: 'Torricelli\'s Law relates to the speed of efflux of a liquid from an opening, not to the excess pressure inside a soap bubble.', difficulty: 'medium' },
  { id: 'mpf-79', type: 'mcq', question: 'Which of the following best summarises the overall scope of this chapter?', options: ['It examines the behaviour of fluids at rest (pressure, Pascal\'s Law, surface tension) and in motion (streamline flow, Bernoulli\'s Principle, viscosity), with numerous practical applications', 'It deals exclusively with the properties of solid materials, with no discussion of liquids or gases', 'It has no connection to any real-world engineering or biological applications', 'It focuses solely on gravitational effects, with no consideration of pressure or flow'], correctIndex: 0, explanation: 'This chapter comprehensively covers both static fluid behaviour (pressure, Pascal\'s Law, surface tension, capillarity) and dynamic fluid behaviour (flow types, Bernoulli\'s Principle, viscosity), with wide-ranging practical applications.', difficulty: 'medium' },
  { id: 'mpf-80', type: 'assertion', question: 'Assertion (A): The principles covered in this chapter have applications ranging from everyday devices (like syringes and drinking straws) to advanced engineering systems (like hydraulic machinery and aircraft design).\nReason (R): Since fluids (liquids and gases) are involved in countless natural and technological processes, understanding their mechanical properties — pressure, flow, viscosity, and surface tension — provides broadly applicable insights across many fields.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The pervasive involvement of fluids in natural and technological systems correctly explains the wide-ranging practical applicability of the concepts covered in this chapter.', difficulty: 'medium' },
  { id: 'mpf-81', type: 'count', question: 'Consider the following statements summarising the chapter:\n1. Pascal\'s Law and Bernoulli\'s Principle both relate to fluid behaviour, but address different aspects (static pressure transmission versus flow-related energy conservation).\n2. Viscosity and surface tension are unrelated concepts, with no shared relevance to fluid behaviour.\n3. Capillary action arises from the interplay of surface tension, adhesive forces, and cohesive forces.\n4. Terminal velocity results from a balance between gravitational, buoyant, and viscous drag forces.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — both viscosity and surface tension are important, related concepts within the broader study of fluid mechanical properties.', difficulty: 'medium' },
  { id: 'mpf-82', type: 'statement', question: 'Statement I: Fluid statics (the study of fluids at rest) and fluid dynamics (the study of fluids in motion) are both essential components of this chapter.\nStatement II: Concepts such as pressure and Pascal\'s Law primarily fall under fluid statics, while concepts such as streamline flow, the equation of continuity, and Bernoulli\'s Principle primarily fall under fluid dynamics.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly categorise the chapter\'s content into fluid statics and fluid dynamics, with accurate examples of concepts belonging to each category.', difficulty: 'medium' },

];